import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        int left = Math.min(n, 5);
        int right = Math.max(0, n - 5);

        System.out.println(left == 0 ? "*" : "I".repeat(left));
        System.out.println(right == 0 ? "*" : "I".repeat(right));
    }
}
